//! 🪢️ Cancellation after retirement reservation closes the real unpublished key and its physical cursor.
use super::*;
use semio_framework_value::{native_decoding::owned::tree::NativeSequenceCollection,retirement::controlled::ControlledRetirement};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[test]
fn original_ui_turn_patch_reservation_keeps_unpublished_ownership_until_paid_close(){
 let mut bank=RetainedCloneGrant{maximum_items:1000000,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:64};let mut fuel=1000000;let mut born=0;let mut freed=0;let(mut storage,heap)=observe(||NativeTurnPatchStorage{patches:UiTurnPatches::default(),candidate:0});assert_eq!(heap,(0,0));
 let post=|bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64,heap:(usize,usize)|{assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();};
 for at in 0..UI_TURN_PATCH_RETIRE_SLOTS+1{if storage.patches.entries[0].retirement.is_some(){break}let d=UiTurnPatches::reserve_demand(&storage,0).unwrap().unwrap();for denied in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let before=storage.candidate;let(turn,heap)=observe(||UiTurnPatches::reserve_step(&mut storage,0,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap(),Default::default());assert_eq!(heap,(0,0));assert_eq!(storage.candidate,before);}let(turn,heap)=observe(||UiTurnPatches::reserve_step(&mut storage,0,bank));post(&mut bank,&mut fuel,turn.result.unwrap(),turn.work,heap);assert!(at<UI_TURN_PATCH_RETIRE_SLOTS);}
 let key=storage.patches.entries[0].retirement.expect("actual reservation remains in unpublished Source storage");assert_eq!(storage.patches.length,1);assert!(storage.patches.entries[0].contents.terminal_is_empty());assert!(storage.patches.iter().next().is_none());let(mut close,heap)=observe(||ControlledRetirement::new(storage).unwrap_or_else(|_|panic!("native patch storage supports paid retirement")));assert_eq!(heap,(0,0));
 for at in 0..100000{if close.terminal_is_empty(){break}let(result,heap)=observe(||close.step(bank));let work=close.last_turn_work();let p=result.unwrap().progress();post(&mut bank,&mut fuel,p,work,heap);born+=p.retained_capacity_bytes;freed+=p.released_bytes;assert!(at<99999)}assert!(close.terminal_is_empty());assert_eq!(born,freed);assert!(fuel>0);let arena=UI_TURN_PATCH_RETIRE_ARENA.lock().unwrap();assert!(!arena.slots[key.slot].reserved||arena.slots[key.slot].epoch!=key.epoch);
}
